/* Desktop rail and matching HTML language/level pickers. Local Chromium only;
 * all source files are served from this checkout. No public site, real account,
 * login, payment, feedback submission, logout or audio request is exercised.
 * The loudspeaker group uses an in-memory speech synthesis double only. */
'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const {execFileSync}=require('node:child_process');
const {test,before,after}=require('node:test');
const {chromium}=require('playwright-core');
const REPO=path.resolve(__dirname,'../..'),WEB=path.join(REPO,'melunga_deploy');
const BASE='a5c721f51a217750c3b83ecd56c85dbfc4ccb7f8',ORIGIN='https://desktop-navigation.test';
const PREVIOUS_TITLE='72a94ca24e5740d4ab467058ef1c0ac9c58ff52a';
const raw=file=>fs.readFileSync(path.join(WEB,file));
const manifest=JSON.parse(raw('content/niveaux-progressifs/manifest.json'));
const sources=['content/niveaux-progressifs/manifest.json',...manifest.pairs.flatMap(p=>[p.repertoirePath,...p.levels.map(l=>l.dataPath)])];
// app.html has a separately owned guest-entry helper in this lot. Protect its
// complete catalogue/family literals here; its account/document flow has its own QA.
const protectedFiles=['index.html','desktop-home.js','course-access.js','content/course-access.json','store-billing.js','account-ui.js','account-ui.css','melunga-logo.png','assets/melunga-logo.png',...fs.readdirSync(path.join(WEB,'netlify/functions')).filter(f=>f.endsWith('.mjs')).map(f=>'netlify/functions/'+f)];
const products=['maquette-guidee.js','maquette-guidee.css','parcours-niveaux.html','maquette-guidee.html'];
const sha=value=>crypto.createHash('sha256').update(value).digest('hex');
const fingerprint=()=>Object.fromEntries([__filename,...sources.concat(protectedFiles,products).map(f=>path.join(WEB,f))].sort().map(f=>[path.relative(REPO,f),sha(fs.readFileSync(f))]));
const checks=['source-conservation','desktop-direct-rail','language-picker','level-picker','shared-menu-actions','mobile-and-legacy','lesson-theme-emphasis','lesson-audio-controls'];
const report={status:'running',baseCommit:BASE,environment:'local Chromium; desktop and phone viewport emulation',publicSiteChecked:false,physicalPhoneChecked:false,realAccountsUsed:false,actualAudioPlayed:false,apiFixture:'read-only GET check-status only',checks:[],cases:[],errors:[],unexpectedRequests:[],screenshots:[]};
let browser,inputs;
const checked=async(name,fn)=>{try{await fn();report.checks.push(name);}catch(error){report.errors.push(name+': '+error.message);throw error;}};
before(async()=>{inputs=fingerprint();browser=await chromium.launch({executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});});
after(async()=>{await browser?.close();report.inputsStable=JSON.stringify(inputs)===JSON.stringify(fingerprint());report.inputSha256=inputs;report.missingChecks=checks.filter(k=>!report.checks.includes(k));report.status=!report.errors.length&&!report.unexpectedRequests.length&&!report.missingChecks.length&&report.inputsStable?'passed':'failed';if(process.env.DESKTOP_NAVIGATION_REPORT)fs.writeFileSync(process.env.DESKTOP_NAVIGATION_REPORT,JSON.stringify(report,null,2)+'\n');assert.equal(report.inputsStable,true,'inputs remain frozen');assert.deepEqual(report.unexpectedRequests,[]);assert.deepEqual(report.errors,[]);assert.deepEqual(report.missingChecks,[]);});
async function fixture({width=1366,height=768,pair='fr-zh',paid=true,legacy=false,previousTitle=false,audio=false,audioGuard=null}={}){
 const context=await browser.newContext({viewport:{width,height},isMobile:width<=760,hasTouch:width<=760,reducedMotion:'reduce',serviceWorkers:'block'});
 await context.addInitScript(enabled=>{
  localStorage.setItem('ox_device','desktop-navigation-fixture');
  window.SpeechSynthesisUtterance=class{constructor(text){this.text=text;}};
  if(!enabled){Object.defineProperty(window,'speechSynthesis',{value:{cancel(){},speak(){throw Error('Unexpected actual audio');},getVoices(){return[];},addEventListener(){}}});return;}
  const locales=['zh-CN','es-ES','en-GB','fr-FR','it-IT','ko-KR','ja-JP'];
  const mock=window.__audioFixture={calls:[],utterances:[],cancels:0,active:null,maxActive:0,throwNext:false,
   voices:locales.flatMap(lang=>[{lang:lang.split('-')[0]+'-XX',voiceURI:lang+':fallback',name:lang+' fallback'},{lang,voiceURI:lang+':exact',name:lang+' exact'},{lang,voiceURI:lang+':preferred',name:lang+' preferred'}]),
   finish(index,error){const u=this.utterances[index];if(this.active===index)this.active=null;if(error)u.onerror?.({error});else u.onend?.();}};
  Object.defineProperty(window,'speechSynthesis',{value:{cancel(){mock.cancels++;mock.active=null;},speak(u){const index=mock.calls.length;mock.calls.push({text:u.text,lang:u.lang,rate:u.rate,voiceURI:u.voice?.voiceURI||null});mock.utterances.push(u);if(mock.throwNext){mock.throwNext=false;throw Error('Simulated synthesis exception');}if(mock.active!==null)throw Error('Concurrent utterances');mock.active=index;mock.maxActive=Math.max(mock.maxActive,1);},getVoices(){return mock.voices;},addEventListener(){}}});
 },audio);
 await context.route('**/*',async route=>{const req=route.request(),url=new URL(req.url());if(url.origin!==ORIGIN){report.unexpectedRequests.push({origin:url.origin,path:url.pathname,method:req.method()});return route.abort();}if(url.pathname==='/.netlify/functions/check-status'&&req.method()==='GET')return route.fulfill({json:{paid}});if(req.method()!=='GET'||/^\/(?:\.netlify|api)\//.test(url.pathname)){report.unexpectedRequests.push({path:url.pathname,method:req.method()});return route.abort();}const file=path.resolve(WEB,decodeURIComponent(url.pathname).replace(/^\//,'')||'parcours-niveaux.html');if(!file.startsWith(WEB+path.sep)||!fs.existsSync(file))return route.fulfill({status:404,body:'Not found'});const type={'.html':'text/html','.js':'text/javascript','.css':'text/css','.json':'application/json','.svg':'image/svg+xml','.png':'image/png','.webp':'image/webp','.woff2':'font/woff2'}[path.extname(file)]||'application/octet-stream';let body=previousTitle&&products.includes(path.relative(WEB,file))?execFileSync('git',['show',PREVIOUS_TITLE+':melunga_deploy/'+path.relative(WEB,file)],{cwd:REPO}):fs.readFileSync(file);if(audioGuard&&file===path.join(WEB,'content/maquette-guidee.json')){const data=JSON.parse(body),theme=data.pairs.find(p=>p.id===pair).themes[0],step=theme.sequences[0].steps[0];if(audioGuard==='template')theme.phrases.find(p=>p.id===step.utterance).isTemplate=true;else if(audioGuard==='choice'){delete step.utterance;step.choices=theme.sequences[0].phraseIds.slice(0,2);}else throw Error('Unknown synthetic audio guard');body=JSON.stringify(data);}return route.fulfill({contentType:type,body});});
 const page=await context.newPage();page.on('pageerror',e=>report.errors.push(e.message));await page.goto(ORIGIN+(legacy?'/maquette-guidee.html':'/parcours-niveaux.html')+'?pair='+pair+'&level=1');await ready(page,pair);return{context,page};
}
async function ready(page,pair,level=1){await page.waitForFunction(({pair,level})=>{const s=window.MelungaMockup?.state();return s?.screen==='themes'&&s.pairId===pair&&s.level===level;},{pair,level});await page.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));}
async function shot(page,name){const target='/tmp/melunga-theme-number-'+name+'.png';await page.screenshot({path:target});report.screenshots.push(target);}
async function fits(page,selector){const b=await page.locator(selector).evaluate(n=>{const r=n.getBoundingClientRect();return{left:r.left,top:r.top,right:r.right,bottom:r.bottom,width:r.width,height:r.height,innerWidth,innerHeight,overflow:document.documentElement.scrollWidth>innerWidth};});assert.ok(b.left>=-1&&b.top>=-1&&b.right<=b.innerWidth+1&&b.bottom<=b.innerHeight+1,selector+' fits '+JSON.stringify(b));assert.equal(b.overflow,false,'no horizontal document overflow');return b;}
async function open(page,trigger,dialog){await page.locator(trigger).click();await page.locator(dialog).waitFor({state:'visible'});await fits(page,dialog);}
async function dismiss(page,dialog){await page.keyboard.press('Escape');await page.locator(dialog).waitFor({state:'hidden'});}
const snapshot=page=>page.evaluate(()=>{const s=window.MelungaMockup.state();return{screen:s.screen,pairId:s.pairId,level:s.level,phraseId:s.phraseId,stepIndex:s.stepIndex,lessonScope:s.lessonScope,known:localStorage.getItem('melunga-guided-known-v1'),review:localStorage.getItem('melunga-guided-review-v1')};});

test('all card, classic, account, pricing and access sources are byte-exact',()=>checked('source-conservation',async()=>{assert.equal(sources.length,78);for(const file of [...sources,...protectedFiles]){const old=execFileSync('git',['show',BASE+':melunga_deploy/'+file],{cwd:REPO,maxBuffer:40*1024*1024});assert.ok(old.equals(raw(file)),'protected whole file '+file);}const classic=raw('app.html').toString(),oldClassic=execFileSync('git',['show',BASE+':melunga_deploy/app.html'],{cwd:REPO,maxBuffer:40*1024*1024}).toString();for(const name of ['DECKS','PEDAGOGY_FAMILIES']){const marker='var '+name+' = ',a=classic.split('\n').filter(line=>line.startsWith(marker)),b=oldClassic.split('\n').filter(line=>line.startsWith(marker));assert.equal(a.length,1);assert.equal(b.length,1);assert.equal(a[0],b[0],'whole classic '+name+' literal unchanged; guest helper flow belongs to separate QA');}report.cases.push({name:'source-conservation',runtimeJson:78,protectedWholeFiles:protectedFiles.length,classicWholeDeckAndFamilyLiterals:true,classicGuestHelperFlowCoveredHere:false});}));

test('wide and short desktop screens expose all nine actions without any sidebar scrolling',()=>checked('desktop-direct-rail',async()=>{
 const sizes=[{width:1024,height:500},{width:1200,height:550},{width:1280,height:480},{width:1280,height:600},{width:1366,height:768},{width:1440,height:900}];
 for(const size of sizes)for(const paid of [false,true]){
  const f=await fixture({...size,paid});
  try{
   const p=f.page,nav=p.locator('#mgDesktopNav'),actions=nav.locator('[data-menu-item]');
   assert.equal(await nav.isVisible(),true);assert.equal(await actions.count(),9);
   assert.deepEqual(await actions.evaluateAll(nodes=>nodes.map(n=>n.dataset.menuItem)),['Accueil','Thèmes','À revoir','review','voice','Couleur','info','feedback',paid?'account':'Se connecter / Créer un compte']);
   assert.equal(await p.locator('#mgDesktopNav [data-menu-item="Toutes les leçons"]').count(),0);
   assert.equal(new URL(await actions.first().getAttribute('href'),ORIGIN).pathname,'/index.html');
   assert.equal(await p.locator('.mg-logo').getAttribute('src'),'melunga-logo.png');
   assert.equal(await p.locator('#mgCounter').textContent(),'L1');assert.equal(await p.locator('#mgLevelEnd').textContent(),'Fin');
   assert.equal(await p.locator('.mg-progress').getAttribute('role'),'progressbar');
   assert.equal(await p.locator('#mgMenuTrigger').isVisible(),false);assert.equal(await p.locator('#mgPalette').isVisible(),false);
   for(const screen of ['themes','lesson']){
    if(screen==='lesson'){await p.locator('#mgThemeGrid .mg-theme').first().click();await p.waitForFunction(()=>window.MelungaMockup.state().screen==='lesson');await p.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));}
    const m=await p.evaluate(()=>{
     const r=n=>{const b=n.getBoundingClientRect();return{left:b.left,top:b.top,right:b.right,bottom:b.bottom,width:b.width,height:b.height};};
     const sidebar=document.querySelector('.mg-sidebar'),nav=document.getElementById('mgDesktopNav');
     return{sidebar:{...r(sidebar),scrollHeight:sidebar.scrollHeight,clientHeight:sidebar.clientHeight,scrollTop:sidebar.scrollTop},nav:{...r(nav),scrollHeight:nav.scrollHeight,clientHeight:nav.clientHeight,scrollTop:nav.scrollTop},actions:[...nav.querySelectorAll('[data-menu-item]')].map(n=>{const label=n.lastElementChild,range=document.createRange();range.selectNodeContents(label);const b=n.getBoundingClientRect(),hit=document.elementFromPoint(b.left+b.width/2,b.top+b.height/2);return{key:n.dataset.menuItem,bounds:r(n),text:label.textContent,textBounds:r(range),font:parseFloat(getComputedStyle(label).fontSize),hit:hit===n||n.contains(hit)};})};
    });
    report.cases.push({name:'short-desktop-rail',...size,paid,screen,geometry:m});
    if((!paid&&size.width===1024&&screen==='themes')||(paid&&((size.width===1200&&screen==='themes')||(size.width===1280&&size.height===480)||(size.width===1440&&screen==='themes'))))await shot(p,'rail-'+screen+'-'+size.width+'x'+size.height);
    assert.ok(m.sidebar.scrollHeight<=m.sidebar.clientHeight,'whole sidebar fits without clipping/scroll: '+JSON.stringify({size,screen,paid,sidebar:m.sidebar}));
    assert.ok(m.nav.scrollHeight<=m.nav.clientHeight,'entire nine-action grid fits its own region');
    assert.equal(m.sidebar.scrollTop,0);assert.equal(m.nav.scrollTop,0);
    for(let i=0;i<9;i++){
     const a=m.actions[i];await fits(p,'#mgDesktopNav [data-menu-item]:nth-child('+(i+1)+')');
     assert.ok(a.bounds.width>=44&&a.bounds.height>=44,'primary target >=44px: '+a.key);
     assert.ok(a.font>=12,'readable captions >=12px: '+a.key+' '+a.font);
     assert.ok(a.text.trim()&&a.textBounds.left>=a.bounds.left-1&&a.textBounds.right<=a.bounds.right+1&&a.textBounds.top>=a.bounds.top-1&&a.textBounds.bottom<=a.bounds.bottom+1,'full caption is laid out inside target: '+JSON.stringify(a));
     assert.ok(a.bounds.left>=m.sidebar.left&&a.bounds.right<=m.sidebar.right&&a.bounds.top>=m.sidebar.top&&a.bounds.bottom<=m.sidebar.bottom,'action lies inside the actual sidebar');
     assert.ok(a.hit,'every action is pointer reachable before focus or scrolling');
     await actions.nth(i).evaluate(n=>n.focus({preventScroll:true}));assert.equal(await actions.nth(i).evaluate(n=>document.activeElement===n),true);
     assert.deepEqual(await p.locator('.mg-sidebar').evaluate(n=>[n.scrollTop,document.getElementById('mgDesktopNav').scrollTop]),[0,0],'focusing never masks clipped rows by scrolling');
    }
   }
  }finally{await f.context.close();}
 }
}));

async function assertLanguageCards(page,selected){
 const layout=await page.locator('#mgLanguageChoices').evaluate(n=>{const b=n.getBoundingClientRect();return{columns:getComputedStyle(n).gridTemplateColumns.trim().split(/\s+/).length,left:b.left,right:b.right,width:b.width};});
 const rows=await page.locator('#mgLanguageChoices .mg-language-option').evaluateAll(nodes=>nodes.map(n=>{
  const r=x=>{const b=x.getBoundingClientRect();return{left:b.left,right:b.right,top:b.top,bottom:b.bottom,width:b.width,height:b.height};};
  const title=n.querySelector('.mg-language-title'),flag=n.querySelector('.mg-language-badge'),tick=getComputedStyle(title,'::after'),style=getComputedStyle(title),badge=getComputedStyle(flag),textRange=document.createRange();textRange.selectNodeContents(title);
  return{pair:n.dataset.pair,flag:flag.textContent,pressed:n.getAttribute('aria-pressed'),bounds:r(n),titleBounds:r(title),titleTextBounds:r(textRange),flagBounds:r(flag),flagLanguage:flag.dataset.language,flagFont:parseFloat(badge.fontSize),flagImage:badge.backgroundImage,font:parseFloat(style.fontSize),weight:Number(style.fontWeight),flagBackground:badge.backgroundColor,flagRadius:badge.borderRadius,tick:{content:tick.content,position:tick.position,right:tick.right,width:tick.width}};
 }));
 assert.equal(layout.columns,1,'language choices form one full-width column');
 assert.deepEqual(rows.map(x=>[x.pair,x.flag,x.flagLanguage]),manifest.pairs.map(x=>[x.id,x.flag,x.studyLanguage]),'source emoji text is preserved while the same language drives the CSS flag');
 assert.deepEqual(rows.filter(x=>x.pressed==='true').map(x=>x.pair),[selected]);
 assert.deepEqual(rows.filter(x=>x.tick.content.includes('✓')).map(x=>x.pair),[selected]);
 for(const row of rows){assert.ok(Math.abs(row.bounds.width-layout.width)<=2,'every language card spans the column');assert.ok(row.bounds.height>=44);assert.ok(row.font>=((await page.viewportSize()).width<=360?20:22),'larger language name remains readable');assert.ok(row.weight>=700);assert.ok(row.flagBounds.left<row.titleBounds.left&&row.flagBounds.right<=row.titleBounds.left,'flag stays at the left');assert.equal(row.flagFont,0,'CSS flags never depend on native emoji-font support');assert.ok(row.flagImage!=='none'||!['rgba(0, 0, 0, 0)','transparent'].includes(row.flagBackground),'every source language has coloured CSS flag artwork');assert.ok(parseFloat(row.flagRadius)<=4,'flag remains rectangular, not a medallion');assert.ok(row.flagBounds.width>row.flagBounds.height&&row.flagBounds.height>=24,'real flag proportions remain readable');}
 const active=rows.find(x=>x.pressed==='true');assert.equal(active.tick.position,'absolute');assert.ok(parseFloat(active.tick.right)>=12&&parseFloat(active.tick.right)<=20,'selected tick is anchored at the far card edge');assert.ok(parseFloat(active.tick.width)>0);assert.ok(active.titleTextBounds.right<=active.bounds.right-parseFloat(active.tick.right)-parseFloat(active.tick.width),'text reserves room for the far-right tick');
 const selectedSource=manifest.pairs.find(p=>p.id===selected);const control=await page.locator('#mgLanguageFlag').evaluate(n=>({language:n.dataset.language,text:n.textContent,font:parseFloat(getComputedStyle(n).fontSize),image:getComputedStyle(n).backgroundImage,colour:getComputedStyle(n).backgroundColor}));assert.equal(control.language,selectedSource.studyLanguage);assert.equal(control.text,selectedSource.flag);assert.equal(control.font,0,'selected top flag also uses the portable CSS artwork');assert.ok(control.image!=='none'||!['rgba(0, 0, 0, 0)','transparent'].includes(control.colour));report.cases.push({name:'full-width-language-layout',selected,width:(await page.viewportSize()).width,layout,rows,selectedControl:control});
 return rows;
}

test('language cards mirror source choices, support keyboard selection and localize for sinophones',()=>checked('language-picker',async()=>{const f=await fixture();try{const p=f.page;assert.equal(await p.locator('#mgLanguage').isVisible(),false,'native select remains state only');await open(p,'#mgLanguageTrigger','#mgLanguageDialog');const choices=p.locator('#mgLanguageChoices .mg-language-option');assert.deepEqual(await choices.evaluateAll(nodes=>nodes.map(n=>n.dataset.pair)),manifest.pairs.map(x=>x.id),'only source-supported pairs appear, in their existing order');assert.equal(await choices.locator('[aria-hidden="true"]').count()>=7,true,'flag/tick decorations are hidden from accessible names');assert.equal(await p.locator('#mgLanguageChoices [aria-pressed="true"]').count(),1);await assertLanguageCards(p,'fr-zh');await shot(p,'desktop-languages-1366x768');await p.keyboard.press('End');await p.keyboard.press('Enter');await ready(p,manifest.pairs.at(-1).id);assert.equal(await p.locator('#mgLanguage').inputValue(),manifest.pairs.at(-1).id);await open(p,'#mgLanguageTrigger','#mgLanguageDialog');await assertLanguageCards(p,manifest.pairs.at(-1).id);await shot(p,'desktop-languages-zh-1366x768');assert.match((await p.locator('#mgLanguageDialog header').textContent()),/[\u3400-\u9fff]/,'dialog header uses learner native Chinese');await dismiss(p,'#mgLanguageDialog');assert.equal(await p.locator('#mgLanguageTrigger').getAttribute('aria-expanded'),'false');assert.equal(await p.locator('#mgLanguageTrigger').evaluate(n=>document.activeElement===n),true,'Escape restores language trigger focus');await open(p,'#mgLanguageTrigger','#mgLanguageDialog');await p.keyboard.press('Home');await p.keyboard.press('Enter');await ready(p,manifest.pairs[0].id);await open(p,'#mgLanguageTrigger','#mgLanguageDialog');await assertLanguageCards(p,manifest.pairs[0].id);await dismiss(p,'#mgLanguageDialog');report.cases.push({name:'language-keyboard-and-localization',sourcePairs:7,selectedPairs:[manifest.pairs.at(-1).id,manifest.pairs[0].id],fullWidthColumn:true,farRightTick:true});}finally{await f.context.close();}for(const size of [{width:390,height:844},{width:320,height:700}]){const phone=await fixture({...size,paid:false});try{await open(phone.page,'#mgLanguageTrigger','#mgLanguageDialog');await assertLanguageCards(phone.page,'fr-zh');await shot(phone.page,'languages-full-width-'+size.width+'x'+size.height);await dismiss(phone.page,'#mgLanguageDialog');report.cases.push({name:'phone-language-cards',...size});}finally{await phone.context.close();}}}));

test('ten level cards keep distinct colours and their keyboard/change lifecycle',()=>checked('level-picker',async()=>{const f=await fixture();try{const p=f.page;await open(p,'#mgLevelTrigger','#mgLevelDialog');const details=await p.locator('#mgLevelChoices button').evaluateAll(nodes=>nodes.map(n=>({level:n.dataset.level,colour:getComputedStyle(n.querySelector('.mg-level-badge')).backgroundColor,selected:n.getAttribute('aria-pressed')})));assert.equal(details.length,10);assert.equal(new Set(details.map(d=>d.colour)).size,10);assert.equal(details.filter(d=>d.selected==='true').length,1);await shot(p,'desktop-levels-1366x768');await p.keyboard.press('End');await p.keyboard.press('Enter');await ready(p,'fr-zh',10);assert.equal(await p.locator('#mgLevel').inputValue(),'10');await open(p,'#mgLevelTrigger','#mgLevelDialog');await dismiss(p,'#mgLevelDialog');assert.equal(await p.locator('#mgLevelTrigger').evaluate(n=>document.activeElement===n),true);await open(p,'#mgLevelTrigger','#mgLevelDialog');await p.keyboard.press('Home');await p.keyboard.press('Enter');await ready(p,'fr-zh',1);report.cases.push({name:'level-keyboard-and-colours',levels:10});}finally{await f.context.close();}}));

test('direct actions reuse existing panels and preserve the current lesson and account state',()=>checked('shared-menu-actions',async()=>{const f=await fixture();try{const p=f.page;await p.locator('#mgThemeGrid .mg-theme').first().click();await p.waitForFunction(()=>window.MelungaMockup.state().screen==='lesson');await shot(p,'desktop-lesson-1366x768');const before=await snapshot(p),url=p.url();const panels={voice:'mgVoicePanel',account:'mgAccountPanel',review:'mgReviewPanel',info:'mgInfoPanel',feedback:'mgFeedbackPanel',saved:'mgSavedReviewPanel'};for(const [key,id] of Object.entries(panels)){const action=p.locator('#mgDesktopNav [data-menu-item="'+(key==='saved'?'À revoir':key)+'"]');await action.focus();await p.keyboard.press('Enter');await p.locator('#mgMenuDialog').waitFor({state:'visible'});await p.locator('#'+id).waitFor({state:'visible'});await fits(p,'#mgMenuDialog');const direct=await p.locator('#mgDesktopNav [data-menu-item]').evaluateAll(nodes=>nodes.map(n=>({key:n.dataset.menuItem,href:n.getAttribute('href')})));const popup=await p.locator('#mgMenuNav [data-menu-item]').evaluateAll(nodes=>nodes.map(n=>({key:n.dataset.menuItem,href:n.getAttribute('href')})));assert.deepEqual(direct,popup,'one action specification feeds both navigation surfaces');await dismiss(p,'#mgMenuDialog');assert.equal(p.url(),url);assert.deepEqual(await snapshot(p),before,'panel navigation preserves lesson and progress');}const ambiance=await p.locator('body').getAttribute('data-ambience');await p.locator('#mgDesktopNav [data-menu-item="Couleur"]').click();const selectedAmbiance=await p.locator('body').getAttribute('data-ambience');assert.notEqual(selectedAmbiance,ambiance);assert.equal(await p.evaluate(()=>sessionStorage.getItem('melunga-course-ambience')),selectedAmbiance,'same shared palette action stores its preference');assert.deepEqual(await snapshot(p),before);await p.locator('#mgDesktopNav [data-menu-item="Thèmes"]').click();await ready(p,'fr-zh');await p.reload();await ready(p,'fr-zh');assert.equal(await p.locator('body').getAttribute('data-ambience'),selectedAmbiance,'page reload restores selected ambience without changing URL');report.cases.push({name:'shared-actions',panels:Object.keys(panels),lessonPreserved:true,posts:0,ambianceRetainedOnReload:true});}finally{await f.context.close();}const guest=await fixture({paid:false});try{const p=guest.page;const login=p.locator('#mgDesktopNav a[href*="login=1"]');assert.equal(await login.count(),1);const q=new URL(await login.getAttribute('href'),ORIGIN).searchParams;assert.equal(q.get('courseReturn'),'fr-zh');assert.equal(q.get('courseLevel'),'1');assert.equal(await p.locator('#mgDesktopNav [data-menu-item="account"]').count(),0);report.cases.push({name:'guest-rights-and-login-link',paid:false});}finally{await guest.context.close();}}));

test('phone four-button controls, popup menu and legacy L1 stay usable',()=>checked('mobile-and-legacy',async()=>{for(const options of [{width:390,height:844},{width:320,height:700},{width:1366,height:768,legacy:true}]){const f=await fixture(options);try{const p=f.page;if(!options.legacy){assert.equal(await p.locator('#mgDesktopNav').isVisible(),false);for(const id of ['mgLevelTrigger','mgLanguageTrigger','mgPalette','mgMenuTrigger']){assert.equal(await p.locator('#'+id).isVisible(),true);await fits(p,'#'+id);}await open(p,'#mgMenuTrigger','#mgMenuDialog');assert.equal(await p.locator('#mgMenuNav [data-menu-item]').count(),9);await dismiss(p,'#mgMenuDialog');await open(p,'#mgLevelTrigger','#mgLevelDialog');await dismiss(p,'#mgLevelDialog');}else assert.equal(await p.locator('#mgLevelTrigger').count(),0,'legacy fixed L1 remains fixed');await open(p,'#mgLanguageTrigger','#mgLanguageDialog');await dismiss(p,'#mgLanguageDialog');if(!options.legacy)await shot(p,'mobile-themes-'+options.width+'x'+options.height);report.cases.push({name:options.legacy?'legacy-fixed-L1':'phone-four-controls',...options});}finally{await f.context.close();}}}));


async function lessonMetrics(page){
 return page.evaluate(()=>{
  const rect=n=>{const r=n.getBoundingClientRect();return{left:r.left,top:r.top,right:r.right,bottom:r.bottom,width:r.width,height:r.height};};
  const rgba=value=>{const c=document.createElement('canvas');c.width=c.height=1;const x=c.getContext('2d');x.fillStyle=value.trim();x.fillRect(0,0,1,1);return[...x.getImageData(0,0,1,1).data];};
  const title=document.getElementById('mgLessonTheme'),card=document.getElementById('mgLessonView'),style=getComputedStyle(title),body=getComputedStyle(document.body);
  const range=document.createRange();range.selectNodeContents(title);
  const fields=['mgPhrase','mgPhon','mgTranslation','mgReading'].map(id=>document.getElementById(id)).filter(n=>!n.hidden&&n.getClientRects().length).map(n=>{const r=document.createRange();r.selectNodeContents(n);return{id:n.id,bounds:rect(r),box:rect(n),font:parseFloat(getComputedStyle(n).fontSize)};});
  const controls=['mgEar','mgReadingToggle','mgListen'].map(id=>document.getElementById(id)).filter(n=>!n.hidden&&n.getClientRects().length).map(n=>({id:n.id,box:rect(n),radius:getComputedStyle(n).borderRadius,background:getComputedStyle(n).backgroundColor}));
  return{themeRole:title.getAttribute('role'),themeLevel:title.getAttribute('aria-level'),themeAria:title.getAttribute('aria-label'),themeTitle:title.getAttribute('title'),titleFlex:{grow:style.flexGrow,shrink:style.flexShrink,basis:style.flexBasis},controls,tools:rect(document.getElementById('mgModelTools')),audioOrder:[...document.getElementById('mgModelTools').children].map(n=>n.id),theme:title.textContent,title:rect(title),titleText:rect(range),card:rect(card),phase:rect(document.getElementById('mgPhaseIcon')),help:rect(document.getElementById('mgHelp')),footer:rect(document.querySelector('.mg-footer')),font:parseFloat(style.fontSize),weight:Number(style.fontWeight),colour:style.color,ink:body.color,borderWidth:parseFloat(style.borderLeftWidth),borderStyle:style.borderLeftStyle,border:rgba(style.borderLeftColor),accent:rgba(body.getPropertyValue('--mg-accent')),background:rgba(style.backgroundColor),soft:rgba(body.getPropertyValue('--mg-soft')),padding:[style.paddingTop,style.paddingRight,style.paddingBottom,style.paddingLeft].map(parseFloat),radii:[style.borderTopLeftRadius,style.borderTopRightRadius,style.borderBottomRightRadius,style.borderBottomLeftRadius],viewport:{width:innerWidth,height:innerHeight,documentWidth:document.documentElement.scrollWidth},fields,scroll:['mgContent','mgLessonView','mgModel'].map(id=>{const n=document.getElementById(id);return{id,vertical:n.scrollHeight-n.clientHeight,horizontal:n.scrollWidth-n.clientWidth};})};
 });
}
function assertLessonFits(m,label){
 for(const n of m.scroll){assert.ok(n.vertical<=2,label+' '+n.id+' has no vertical scrolling '+JSON.stringify(n));assert.ok(n.horizontal<=2,label+' '+n.id+' has no horizontal scrolling');}
 assert.ok(m.viewport.documentWidth<=m.viewport.width+1,label+' document does not overflow');
 assert.ok(m.card.left>=-1&&m.card.top>=-1&&m.card.right<=m.viewport.width+1&&m.card.bottom<=m.viewport.height+1,label+' card stays on screen');
 assert.ok(m.card.bottom<=m.footer.top+1,label+' card does not overlap the footer');
 for(const n of [{id:'theme-title',bounds:m.titleText},...m.fields]){assert.ok(n.bounds.left>=m.card.left-1&&n.bounds.right<=m.card.right+1,label+' '+n.id+' fits horizontally');assert.ok(n.bounds.top>=m.card.top-1&&n.bounds.bottom<=m.card.bottom+1,label+' '+n.id+' fits vertically');}
 assert.ok(m.title.right<=m.phase.left+1,label+' title leaves room for phase control');
 // A Range includes empty font ascenders beyond its element box. Check the
 // painted banner against layout boxes, and text against the other text.
 assert.ok(m.title.bottom<=Math.min(...m.fields.map(n=>n.box.top))+1,label+' banner does not overlap learning elements '+JSON.stringify({title:m.title,fields:m.fields}));
 assert.ok(m.titleText.bottom<=Math.min(...m.fields.map(n=>n.bounds.top))+1,label+' theme text does not overlap learning text');
 for(let a=0;a<m.fields.length;a++)for(let b=a+1;b<m.fields.length;b++){const x=m.fields[a].bounds,y=m.fields[b].bounds;assert.ok(Math.min(x.right,y.right)-Math.max(x.left,y.left)<=1||Math.min(x.bottom,y.bottom)-Math.max(x.top,y.top)<=1,label+' card text does not overlap');}
 const speaker=m.controls.find(n=>n.id==='mgListen'),translation=m.fields.find(n=>n.id==='mgTranslation');assert.ok(speaker,label+' loudspeaker remains visible');assert.deepEqual(m.audioOrder,['mgReadingToggle','mgListen'],label+' Pinyin then loudspeaker follow translation');assert.ok(speaker.box.top>=translation.box.bottom-1,label+' loudspeaker stays under translation');assert.ok(Math.abs(speaker.box.width-speaker.box.height)<1&&speaker.box.width>=44,label+' round accessible audio target');assert.equal(speaker.radius,'50%');assert.equal(speaker.background,'rgb(57, 191, 255)',label+' approved blue audio button');
 for(const n of m.controls){assert.ok(n.box.left>=m.card.left-1&&n.box.right<=m.card.right+1&&n.box.top>=m.card.top-1&&n.box.bottom<=m.card.bottom+1,label+' '+n.id+' fits card');assert.ok(n.box.bottom<=m.footer.top+1,label+' '+n.id+' leaves footer clear');for(const field of m.fields){const x=n.box,y=field.bounds;assert.ok(Math.min(x.right,y.right)-Math.max(x.left,y.left)<=1||Math.min(x.bottom,y.bottom)-Math.max(x.top,y.top)<=1,label+' '+n.id+' does not overlap '+field.id);}}
 const readingToggle=m.controls.find(n=>n.id==='mgReadingToggle');if(readingToggle){const x=speaker.box,y=readingToggle.box;assert.ok(Math.min(x.right,y.right)-Math.max(x.left,y.left)<=1||Math.min(x.bottom,y.bottom)-Math.max(x.top,y.top)<=1,label+' Pinyin and loudspeaker stay separate');}
}
function assertBanner(m,size,label){
 assert.match(m.theme,/^\d{2,}$/u,label+' only the theme number is visible');assert.equal(m.themeRole,'heading',label+' number retains heading semantics');assert.equal(m.themeLevel,'2');assert.ok(m.themeAria.startsWith(m.theme+' · ')&&m.themeAria.length>m.theme.length+3,label+' accessible name retains the complete theme title');assert.equal(m.themeTitle,m.themeAria,label+' tooltip retains the complete label');assert.deepEqual(m.titleFlex,{grow:'0',shrink:'1',basis:'auto'},label+' number badge remains compact');
 assert.ok(Math.abs(m.font-(size.width<=760?16:Math.min(24,Math.max(20,size.width*.015))))<.02,label+' responsive theme label size unchanged');
 assert.equal(m.weight,800,label+' title keeps its approved weight');assert.equal(m.colour,m.ink,label+' title keeps full foreground colour');
 assert.equal(m.borderWidth,4,label+' accent stripe is four pixels');assert.equal(m.borderStyle,'solid');assert.deepEqual(m.border,m.accent,label+' stripe follows the chosen ambience accent');assert.deepEqual(m.background,m.soft,label+' banner uses the existing soft surface');
 assert.deepEqual(m.padding,size.width<=760?[8,10,8,10]:[12,14,12,14],label+' compact responsive padding');assert.deepEqual(m.radii,['0px','14px','14px','0px'],label+' only right corners are rounded');
 assert.ok(m.titleText.left>=m.title.left+m.borderWidth+m.padding[3]-1&&m.titleText.right<=m.title.right-m.padding[1]+1,label+' complete title stays inside the padded banner');
 assert.ok(m.titleText.top>=m.title.top+m.padding[0]-1&&m.titleText.bottom<=m.title.bottom-m.padding[2]+1,label+' complete title fits banner height');
 assertLessonFits(m,label);
}
function realLongCard(pair,level,themeId,phraseId){
 const data=JSON.parse(raw('content/niveaux-progressifs/'+pair+'/L'+level+'.json')),theme=data.themes.find(t=>t.id===themeId);assert.ok(theme,'real stress theme exists');
 const target=theme.sequences.flatMap(s=>s.steps).findIndex(s=>s.utterance===phraseId&&s.kind==='understand'),phrase=theme.phrases.find(p=>p.id===phraseId);assert.ok(target>=0&&phrase,'long source phrase is prepared in this real theme');return{pair,level,data,theme,phraseId,phrase,target};
}
async function enterLong(page,card){
 await page.goto(ORIGIN+'/parcours-niveaux.html?pair='+card.pair+'&level='+card.level);await ready(page,card.pair,card.level);await page.locator('#mgThemeGrid .mg-theme').nth(card.data.themes.indexOf(card.theme)).click();await page.waitForFunction(()=>window.MelungaMockup.state().screen==='lesson');await page.evaluate(count=>{for(let n=0;n<count;n++){document.querySelector('#mgChoices:not([hidden]) button')?.click();document.getElementById('mgContinue').click();}},card.target);await page.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));assert.equal(await page.evaluate(()=>window.MelungaMockup.state().phraseId),card.phraseId);
}
async function ambience(page,value){await page.locator('body').evaluate((n,v)=>{n.dataset.ambience=v;},value);await page.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));}

