  for(const value of ambiences){await ambience(p,value);const m=await lessonMetrics(p);assertBanner(m,size,'first '+pair+' '+size.width+' '+value);if(pair==='fr-zh'&&[1366,390].includes(size.width))await shot(p,'theme-banner-first-'+value+'-'+size.width+'x'+size.height);report.cases.push({name:'theme-title-first-card',pair,...size,ambience:value,measure:m});}
  const firstState=await snapshot(p);await p.locator('#mgContinue').click();await p.locator('#mgContinue').click();const nextState=await snapshot(p);assert.notEqual(nextState.phraseId,firstState.phraseId,'two real cards were visited');assert.equal(await p.locator('#mgLessonTheme').textContent(),listNumber,'theme number stays stable across two cards');assert.equal(await p.locator('#mgLessonTheme').getAttribute('aria-label'),fullLabel);assert.equal(nextState.known,firstState.known);assert.equal(nextState.review,firstState.review);report.cases.push({name:'theme-number-stable-between-cards',pair,...size,number:listNumber,phrases:[firstState.phraseId,nextState.phraseId]});
  if([1366,390].includes(size.width)){const beforeMenu=await snapshot(p);await open(p,size.width<=760?'#mgMenuTrigger':'#mgDesktopNav [data-menu-item="review"]','#mgMenuDialog');if(size.width<=760)await p.locator('#mgMenuNav [data-menu-item="review"]').click();await p.locator('#mgReviewPanel').waitFor({state:'visible'});const labels=await p.locator('#mgReviewTheme option').allTextContents();assert.ok(labels.includes(fullLabel),'review menu retains the complete numbered theme title');await dismiss(p,'#mgMenuDialog');assert.deepEqual(await snapshot(p),beforeMenu,'review-menu inspection preserves the current card');report.cases.push({name:'full-theme-title-in-review-menu',pair,...size,label:fullLabel});}
  const card=longCards[pair];await enterLong(p,card);
  for(const value of ambiences){await ambience(p,value);const m=await lessonMetrics(p);assert.equal(m.theme,String(card.data.themes.indexOf(card.theme)+1).padStart(2,'0'),'long card number follows the actual theme list');assert.equal(m.themeAria,m.theme+' · '+card.theme.title,'long complete title remains accessible');assertBanner(m,size,'long '+pair+' '+size.width+' '+value);if(value==='ocean'||size.width===390&&pair==='fr-zh')await shot(p,'theme-banner-long-'+pair+'-'+value+'-'+size.width+'x'+size.height);report.cases.push({name:'theme-title-long-card',pair,...size,ambience:value,phraseId:card.phraseId,measure:m});}
  if(pair==='fr-zh'&&size.width===390){await ambience(p,'ocean');await p.locator('#mgReadingToggle').click();await p.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));assert.equal(await p.locator('#mgReadingToggle').getAttribute('aria-pressed'),'true');assert.equal(await p.locator('#mgPhon').textContent(),card.phrase.reading,'the real Pinyin is shown');const m=await lessonMetrics(p);assertBanner(m,size,'long Chinese mobile with Pinyin');await shot(p,'theme-banner-long-fr-zh-pinyin-390x844');report.cases.push({name:'theme-title-pinyin-long-card',pair,...size,phraseId:card.phraseId,measure:m});}
  if(pair==='fr-zh'){await enterLong(p,english);const m=await lessonMetrics(p);if([320,390,1280].includes(size.width))await shot(p,'theme-banner-long-fr-en-'+size.width+'x'+size.height);assertBanner(m,size,'preserved English stress '+size.width);report.cases.push({name:'theme-title-existing-English-stress',pair:english.pair,...size,phraseId:english.phraseId,measure:m});}
